package io.knowledgebrain.knowledge;
import java.time.*;
import java.util.*;
import org.junit.jupiter.api.Test;
import org.springframework.mock.web.MockHttpServletRequest;
import jakarta.servlet.http.Cookie;
import org.springframework.web.server.ResponseStatusException;
import tools.jackson.databind.json.JsonMapper;
import io.micrometer.core.instrument.simple.SimpleMeterRegistry;
import static org.mockito.Mockito.*;
import static org.assertj.core.api.Assertions.*;
class PublicRecordApiTest {
    PublicRecordStore store=mock(PublicRecordStore.class);SpaceAuthorizationClient space=mock(SpaceAuthorizationClient.class);ConceptController browser=mock(ConceptController.class);PublicRecordController api=new PublicRecordController(store,space,browser,new SimpleMeterRegistry(),"https://localhost:8443");UuidV7 ids=new UuidV7(Clock.systemUTC());UUID catalog=ids.next(),id=ids.next(),actor=ids.next();
    MockHttpServletRequest request(String method,String body){var r=new MockHttpServletRequest(method,"/api/public/spaces/"+catalog+"/record-proposals/"+id+"/review");r.setSecure(true);r.setCookies(new Cookie("__Host-brain_guest","a".repeat(43)));r.addHeader("Origin","https://localhost:8443");r.setContentType("application/json");r.setContent(body.getBytes(java.nio.charset.StandardCharsets.UTF_8));when(browser.parent(r)).thenReturn("00-"+"a".repeat(32)+"-"+"b".repeat(16)+"-01");when(space.authorize(eq(catalog),anyString(),anyString(),eq("PUBLIC"),anyString())).thenReturn(actor);return r;}
    @Test void crossOriginDuplicateCookiesAndJsonNeverMutate()throws Exception{var cross=request("POST","{}");cross.removeHeader("Origin");cross.addHeader("Origin","https://evil.invalid");assertThatThrownBy(()->api.submit(catalog,cross)).isInstanceOf(ResponseStatusException.class);var duplicate=request("POST","{}");duplicate.setCookies(new Cookie("__Host-brain_guest","a".repeat(43)),new Cookie("__Host-brain_guest","b".repeat(43)));assertThatThrownBy(()->api.submit(catalog,duplicate)).isInstanceOf(ResponseStatusException.class);var body=request("POST","{\"kind\":\"SOURCE\",\"kind\":\"CLAIM\"}");assertThatThrownBy(()->api.submit(catalog,body)).isInstanceOf(ResponseStatusException.class);verifyNoInteractions(store);}
    @Test void missingAndWeakVersionsNeverWrite()throws Exception{var r=request("POST","{\"decision\":\"REJECTED\",\"reason\":\"Fix\"}");assertThatThrownBy(()->api.decide(catalog,id,"review",r)).isInstanceOf(ResponseStatusException.class).satisfies(e->assertThat(((ResponseStatusException)e).getStatusCode().value()).isEqualTo(428));r.addHeader("If-Match","W/\"kp1\"");assertThatThrownBy(()->api.decide(catalog,id,"review",r)).isInstanceOf(ResponseStatusException.class);verify(store,never()).decide(any(),any(),any(),anyLong(),anyString(),anyString(),anyString());}
    @Test void expertApprovalAndMergeRequireFreshAdditionalSpaceAuthority()throws Exception{var content=JsonMapper.builder().build().createObjectNode().put("level","EXPERT_VERIFIED");var p=new PublicRecordStore.Proposal(id,catalog,ids.next(),"VERIFICATION","UPDATE",1,"Expert",content,"Reason",ids.next(),"SUBMITTED",1,null,Instant.now(),Instant.now(),JsonMapper.builder().build().createObjectNode());when(store.proposal(catalog,id)).thenReturn(p);when(store.authority(p)).thenReturn("CLAIM_EXPERT_VERIFY");var r=request("POST","{\"decision\":\"APPROVED\",\"reason\":\"Reviewed\"}");r.addHeader("If-Match","\"kp1\"");doThrow(new ResponseStatusException(org.springframework.http.HttpStatus.FORBIDDEN)).when(space).authorize(eq(catalog),anyString(),eq("CLAIM_EXPERT_VERIFY"),eq("PUBLIC"),anyString());assertThatThrownBy(()->api.decide(catalog,id,"review",r)).isInstanceOf(ResponseStatusException.class);verify(store,never()).decide(any(),any(),any(),anyLong(),anyString(),anyString(),anyString());verify(space).authorize(eq(catalog),anyString(),eq("CONTRIBUTION_REVIEW"),eq("PUBLIC"),anyString());}
    @Test void unknownAndDuplicateQueryParametersAreRejectedBeforeStoreReads(){var r=request("GET","");r.addParameter("kind","CLAIM","SOURCE");assertThatThrownBy(()->api.list(catalog,"CLAIM","ACTIVE",null,10,"",r)).isInstanceOf(ResponseStatusException.class);verifyNoInteractions(store);}
}
